# Find the largest "solid" rectangle in the demo
def find_max_solid_rectangle(grid):
    """Find the largest completely filled rectangular block."""
    h, w = len(grid), len(grid[0])
    max_area = 0
    max_rect = None

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                continue
            color = grid[r][c]

            # Find the bounding box of this color that's completely filled
            # Start with minimal box: 1x1
            r_min, r_max, c_min, c_max = r, r, c, c

            # Extend horizontally
            while c_max + 1 < w and grid[r][c_max + 1] == color:
                c_max += 1

            # Extend vertically
            while r_max + 1 < h:
                can_extend = True
                for col in range(c_min, c_max + 1):
                    if grid[r_max + 1][col] != color:
                        can_extend = False
                        break
                if can_extend:
                    r_max += 1
                else:
                    break

            # Now check if the rectangle (r_min, c_min) to (r_max, c_max) is fully filled
            area = (r_max - r_min + 1) * (c_max - c_min + 1)
            all_filled = all(grid[i][j] == color 
                           for i in range(r_min, r_max + 1) 
                           for j in range(c_min, c_max + 1))

            if all_filled and area > max_area:
                max_area = area
                max_rect = ((r_min, c_min), (r_max, c_max), color)

    return max_rect

